1	import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises'
2	import { join } from 'node:path'
3	import type { SessionMode } from './session-manager'
4	
5	export type Hand = { sessionId: string; mode: SessionMode; feature?: string }
6	
7	type Registry = { id: string; mode: SessionMode; feature?: string; files: Record<string, number> }
8	
9	/** Where each session's own writes land, on disk so another session — another process, another window — can look them up: nothing here assumes they share memory. */
10	const dirFor = (workspaceRoot: string): string => join(workspaceRoot, '.agent', 'sessions')
11	
12	/**
13	 * Attributes a file's content to the KiwiAgent session that last wrote it, so
14	 * a stale-write refusal can name who: this session's own writes go in here,
15	 * another session's are read back off disk. A thin attribution log, not the
16	 * fuller claim registry (deadlines, heartbeats, denying a live session's
17	 * hold) `docs/features/coordination.md#Claims` describes — nothing this
18	 * feature's rules ask for yet needs those.
19	 */
20	export class FileHands {
21	  constructor(
22	    private readonly workspaceRoot: string,
23	    private readonly sessionId: string,
24	    private readonly mode: SessionMode,
25	    private readonly feature: string | undefined,
26	  ) {}
27	
28	  /** Records that this session's own write left `path` at `mtimeMs`. */
29	  async recordWrite(path: string, mtimeMs: number): Promise<void> {
30	    const dir = dirFor(this.workspaceRoot)
31	    const file = join(dir, `${this.sessionId}.json`)
32	    const registry: Registry = (await readRegistry(file)) ?? {
33	      id: this.sessionId,
34	      mode: this.mode,
35	      ...(this.feature !== undefined ? { feature: this.feature } : {}),
36	      files: {},
37	    }
38	    registry.files[path] = mtimeMs
39	    await mkdir(dir, { recursive: true })
40	    await writeFile(file, JSON.stringify(registry), 'utf8').catch(() => undefined)
41	  }
42	
43	  /** The other KiwiAgent session whose own write left `path` at exactly `mtimeMs`, if one did. */
44	  async whoWrote(path: string, mtimeMs: number): Promise<Hand | undefined> {
45	    let names: string[]
46	    try {
47	      names = await readdir(dirFor(this.workspaceRoot))
48	    } catch {
49	      return undefined
50	    }
51	    for (const name of names) {
52	      if (name === `${this.sessionId}.json`) continue
53	      const registry = await readRegistry(join(dirFor(this.workspaceRoot), name))
54	      if (registry && registry.files[path] === mtimeMs) {
55	        return { sessionId: registry.id, mode: registry.mode, ...(registry.feature !== undefined ? { feature: registry.feature } : {}) }
56	      }
57	    }
58	    return undefined
59	  }
60	}
61	
62	async function readRegistry(file: string): Promise<Registry | undefined> {
63	  try {
64	    return JSON.parse(await readFile(file, 'utf8')) as Registry
65	  } catch {
66	    return undefined
67	  }
68	}
