70	/**
71	 * What a refusal or notice says about where a change came from: the other
72	 * KiwiAgent session and the feature it works on when the registry names one,
73	 * outside KiwiAgent otherwise — never which tool made the change.
74	 */
75	export function describeHand(hand: Hand | undefined): string {
76	  if (!hand) return 'It was changed from outside KiwiAgent.'
77	  const who = hand.feature ? `a KiwiAgent ${hand.mode} session on "${hand.feature}"` : `a KiwiAgent ${hand.mode} session`
78	  return `It was changed by ${who}.`
79	}
